# Replica Consistency Checker demo: Merkle-style root compare + divergence list.
import hashlib
def root(recs): return hashlib.sha256("".join(sorted(recs)).encode()).hexdigest()[:12]
A={"r1":"v2","r2":"v1","r3":"v1"}; B={"r1":"v1","r2":"v1","r4":"v1"}
ra=root(k+v for k,v in A.items()); rb=root(k+v for k,v in B.items())
print("roots equal:",ra==rb)
for k in sorted(set(A)|set(B)):
    a,b=A.get(k),B.get(k)
    if a!=b: print("divergent",k,"replicaA=%s replicaB=%s"%(a,b))

